/**
 * @param {Array} arr
 * @return {Generator}
 */
var inorderTraversal = function*(arr) {
    // Stack of iterators, one per array we are currently inside
    const stack = [arr[Symbol.iterator]()];

    while (stack.length > 0) {
        // Advance the innermost array we are in
        const { value, done } = stack[stack.length - 1].next();

        if (done) {
            // Finished this array, go back to its parent
            stack.pop();
        } else if (Array.isArray(value)) {
            // Descend into the nested array
            stack.push(value[Symbol.iterator]());
        } else {
            // An integer: hand it to the caller
            yield value;
        }
    }
};

